constraints:
1<=|S|<=10^{5}

expected time complexity: O(|S|)
expected auxiliary space: O(|S|)

standard_solution_code:
class Solution:

	def rremove(self, S):

		def rec(S):
			ans = ''
			n = len(S)
			i = 0
			while i < n:
				if i < n - 1 and S[i] == S[i + 1]:
					while i < n - 1 and S[i] == S[i + 1]:
						i += 1
				else:
					ans += S[i]
				i += 1
			return ans
		s1 = ''
		while len(S) != len(s1):
			s1 = S
			S = rec(S)
		return S
